// Assert artifact-detector spawned as first subagent
const meta = context.providerResponse?.metadata;
const tcs = meta?.toolCalls ?? [];
const subagentCalls = tcs.filter(tc => ['Task', 'task', 'Agent', 'agent'].includes(tc.name));
const firstSubagent = subagentCalls[0];
if (!firstSubagent) return { pass: false, score: 0, reason: 'No subagent calls found' };
const input = JSON.stringify(firstSubagent.input);
