const meta = context.providerResponse?.metadata;
const cmds = meta?.bashCommands ?? [];
const hasWorkUpdate = cmds.some(c => c.includes('rp1 agent-tools work update') && c.includes('--workflow') && c.includes('--run-id'));
if (!hasWorkUpdate) return { pass: false, score: 0, reason: 'No work status update found in bash commands' };
return { pass: true, score: 1, reason: 'Work status update found' };

// Assert NO AskUserQuestion calls (AFK mode)
const meta = context.providerResponse?.metadata;
const tcs = meta?.toolCalls ?? [];
const askCall = tcs.find(tc => tc.name === 'AskUserQuestion');
if (askCall) return { pass: false, score: 0, reason: 'Found AskUserQuestion in AFK mode' };
return { pass: true, score: 1, reason: 'No AskUserQuestion calls in AFK mode' };

// Assert PROHIBITED commands not present
const meta = context.providerResponse?.metadata;
const cmds = meta?.bashCommands ?? [];
const prohibited = [
  { pattern: /git push (--force|-f)/, label: 'git push --force' },
  { pattern: /\bgit\b.*\bcommit\b/, label: 'git commit (not expected without GIT_COMMIT flag)' },
  { pattern: /\bgit\s+reset\s+--hard\b/, label: 'git reset --hard' },
  { pattern: /\bgit\s+rebase\b/, label: 'git rebase' },
