/**
 * YAML validator module — validates YAML syntax without external dependencies.
 */

/**
 * Result of YAML validation.
 */
export interface YamlValidationResult {
  valid: boolean;
  error?: string;
  line?: number;
}

/**
 * Check if a string value looks like a valid YAML scalar value.
 */
function isValidScalar(value: string): boolean {
  const trimmed = value.trim();

  // Empty value (implicit null)
  if (trimmed === "") return true;

  // Null
  if (trimmed === "null" || trimmed === "~") return true;

  // Booleans
  if (
    trimmed === "true" ||
    trimmed === "false" ||
    trimmed === "yes" ||
    trimmed === "no" ||
    trimmed === "on" ||
    trimmed === "off"
  )
    return true;

  // Numbers (integer or float)
  if (/^-?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(trimmed)) return true;

  // Quoted strings
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return true;
  }

  // Unquoted string — valid as long as it doesn't have problematic chars
  // Allow most characters in unquoted strings
  return true;
}

/**
 * Check for unclosed quotes in a string.
 */
function hasUnclosedQuotes(value: string): boolean {
  const trimmed = value.trim();

  if (trimmed.startsWith('"') && !trimmed.endsWith('"')) return true;
  if (trimmed.startsWith("'") && !trimmed.endsWith("'")) return true;

  // Single quote or double quote in the middle without matching pair
  if (trimmed.endsWith('"') && !trimmed.startsWith('"')) {
    const idx = trimmed.indexOf('"');
    if (idx === trimmed.length - 1) return false;
  }
  if (trimmed.endsWith("'") && !trimmed.startsWith("'")) {
    const idx = trimmed.indexOf("'");
    if (idx === trimmed.length - 1) return false;
  }

  return false;
}

/**
 * Get the indentation level (number of leading spaces) of a line.
 */
function getIndent(line: string): number {
  const match = line.match(/^( *)/);
  return match ? match[1].length : 0;
}

/**
 * Validate a string as YAML and return a structured result.
 */
export function validateYaml(input: string): YamlValidationResult {
  // Empty input is valid (empty document)
  if (input.trim() === "") {
    return { valid: true };
  }

  const lines = input.split("\n");

  // Track keys at each indentation level for duplicate detection
  const keysAtLevel: Map<number, Set<string>> = new Map();

  // Track the expected indentation context
  const indentStack: number[] = [0];

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Skip empty lines
    if (line.trim() === "") continue;

    // Check for tab indentation (YAML forbids tabs)
    if (/^\t/.test(line) || /\t/.test(line.substring(0, line.indexOf(line.trim())))) {
      return {
        valid: false,
        error: "Tab characters are not allowed for indentation in YAML",
        line: lineNum,
      };
    }

    // Skip comment-only lines
    if (line.trim().startsWith("#")) continue;

    const indent = getIndent(line);
    const content = line.trim();

    // Indentation must be spaces in even amounts (or consistent)
    if (indent % 2 !== 0) {
      // Odd indentation is technically allowed in YAML but we enforce consistency
      // Actually, YAML allows any consistent indentation, so let's be lenient
      // We'll just check that it's consistent with parent
    }

    // Handle indentation changes
    const currentLevel = indentStack[indentStack.length - 1];

    if (indent > currentLevel) {
      // Indenting deeper — push new level
      indentStack.push(indent);
      // New indentation level resets key tracking at this level
      keysAtLevel.set(indent, new Set());
    } else if (indent < currentLevel) {
      // Dedenting — pop levels until we find a match
      while (
        indentStack.length > 1 &&
        indentStack[indentStack.length - 1] > indent
      ) {
        const popped = indentStack.pop()!;
        keysAtLevel.delete(popped);
      }

      // After popping, the indent should match the current stack top
      if (indentStack[indentStack.length - 1] !== indent) {
        return {
          valid: false,
          error: `Inconsistent indentation: expected ${indentStack[indentStack.length - 1]} spaces but found ${indent}`,
          line: lineNum,
        };
      }
    }

    // Ensure key set exists for this level
    if (!keysAtLevel.has(indent)) {
      keysAtLevel.set(indent, new Set());
    }

    // Determine what kind of line this is
    const isListItem = /^\s*-\s/.test(line) || /^\s*-$/.test(line);
    const keyValueMatch = content.match(/^([^:#\s][^:#]*?)\s*:\s*(.*)?$/);
    const listKeyValueMatch = content.match(/^-\s+([^:#\s][^:#]*?)\s*:\s*(.*)?$/);

    if (isListItem) {
      // List item
      const afterDash = content.substring(1).trim();

      // List item with key-value (e.g., "- name: foo")
      if (listKeyValueMatch) {
        const value = listKeyValueMatch[2] ?? "";
        if (hasUnclosedQuotes(value)) {
          return {
            valid: false,
            error: "Unclosed quote in value",
            line: lineNum,
          };
        }
      } else if (afterDash !== "" && hasUnclosedQuotes(afterDash)) {
        return {
          valid: false,
          error: "Unclosed quote in value",
          line: lineNum,
        };
      }
    } else if (keyValueMatch) {
      // Key-value pair
      const key = keyValueMatch[1].trim();
      const value = keyValueMatch[2] ?? "";

      // Check for duplicate keys at this indentation level
      const levelKeys = keysAtLevel.get(indent)!;
      if (levelKeys.has(key)) {
        return {
          valid: false,
          error: `Duplicate key "${key}"`,
          line: lineNum,
        };
      }
      levelKeys.add(key);

      // Check value for unclosed quotes
      if (hasUnclosedQuotes(value)) {
        return {
          valid: false,
          error: "Unclosed quote in value",
          line: lineNum,
        };
      }

      // Check for multiple colons that indicate bad syntax (e.g., "key: : value")
      if (value.trim().startsWith(":")) {
        return {
          valid: false,
          error: "Invalid value: unexpected colon",
          line: lineNum,
        };
      }
    } else if (content.startsWith("---") || content.startsWith("...")) {
      // Document markers — valid
      continue;
    } else {
      // Doesn't match any known YAML pattern
      // Could be a block scalar continuation or just invalid
      // If it looks like a bare value following a parent key, that's okay
      // But if it's at the root level with no context, it's suspicious
      if (indent === 0 && !content.startsWith("-")) {
        // Root-level line that's not a key-value, list item, comment, or doc marker
        // Check if it could be a plain scalar (single-document bare value)
        if (lines.filter((l) => l.trim() !== "" && !l.trim().startsWith("#")).length === 1) {
          // Single non-empty line as bare scalar — valid
          continue;
        }
        // Multiple root-level non-key-value lines is invalid
        return {
          valid: false,
          error: "Invalid YAML syntax: expected key-value pair or list item",
          line: lineNum,
        };
      }
    }
  }

  return { valid: true };
}

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("valid YAML", () => {
    test("simple key-value pair", () => {
      const result = validateYaml("name: John");
      expect(result.valid).toBe(true);
    });

    test("multiple key-value pairs", () => {
      const result = validateYaml("name: John\nage: 30\ncity: NYC");
      expect(result.valid).toBe(true);
    });

    test("nested objects", () => {
      const yaml = `person:
  name: John
  age: 30
  address:
    street: 123 Main St
    city: NYC`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("arrays with dash prefix", () => {
      const yaml = `fruits:
  - apple
  - banana
  - cherry`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("array of objects", () => {
      const yaml = `people:
  - name: Alice
    age: 25
  - name: Bob
    age: 30`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("boolean values", () => {
      const yaml = `active: true\nenabled: false\nverbose: yes\nquiet: no`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("null values", () => {
      const yaml = `empty: null\nalso_empty: ~`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("number values", () => {
      const yaml = `count: 42\nprice: 9.99\nnegative: -5`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("quoted strings", () => {
      const yaml = `single: 'hello world'\ndouble: "hello world"`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("comments are ignored", () => {
      const yaml = `# This is a comment
name: John
# Another comment
age: 30`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("blank lines are ignored", () => {
      const yaml = `name: John

age: 30

city: NYC`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("empty input", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
    });

    test("whitespace-only input", () => {
      const result = validateYaml("   \n  \n   ");
      expect(result.valid).toBe(true);
    });

    test("document markers", () => {
      const yaml = `---
name: John
age: 30
...`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("mixed structure", () => {
      const yaml = `database:
  host: localhost
  port: 5432
  credentials:
    username: admin
    password: secret
  replicas:
    - host: replica1
      port: 5433
    - host: replica2
      port: 5434`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML", () => {
    test("tab indentation", () => {
      const yaml = "name:\n\tvalue: test";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Tab");
      expect(result.line).toBe(2);
    });

    test("duplicate keys at same level", () => {
      const yaml = `name: John\nage: 30\nname: Jane`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Duplicate key");
      expect(result.line).toBe(3);
    });

    test("unclosed double quote", () => {
      const yaml = `name: "John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unclosed quote");
    });

    test("unclosed single quote", () => {
      const yaml = `name: 'John`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unclosed quote");
    });

    test("invalid value with unexpected colon", () => {
      const yaml = `name: : invalid`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("colon");
    });

    test("inconsistent indentation", () => {
      const yaml = `parent:
  child1: value
    child2: value`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("indentation");
    });

    test("returns line number on error", () => {
      const yaml = `name: John\nage: 30\nbad: : value`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.line).toBe(3);
    });
  });

  describe("result structure", () => {
    test("valid result has no error or line", () => {
      const result = validateYaml("key: value");
      expect(result).toEqual({ valid: true });
    });

    test("invalid result has error and line", () => {
      const result = validateYaml("key: : bad");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.line).toBeDefined();
    });
  });
});

/**
 * CLI entry point for YAML validation.
 * Usage: bun run src/validate-yaml.ts <file>
 */

import { validateYaml } from "./yaml-validator";

const filePath = process.argv[2];

if (!filePath) {
  console.error("Usage: bun run src/validate-yaml.ts <file>");
  process.exit(1);
}

const file = Bun.file(filePath);
const exists = await file.exists();

if (!exists) {
  console.error(`File not found: ${filePath}`);
  process.exit(1);
}

const content = await file.text();
const result = validateYaml(content);

if (result.valid) {
  console.log("Valid YAML");
} else {
  console.error(
    `Invalid YAML${result.line ? ` (line ${result.line})` : ""}: ${result.error}`
  );
  process.exit(1);
}

