        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validator\";\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"simple key-value pairs\", () => {\n      const yaml = `name: Alice\\nage: 30\\ncity: Wonderland`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"nested YAML\", () => {\n      const yaml = [\n        \"server:\",\n        \"  host: localhost\",\n        \"  port: 8080\",\n        \"database:\",\n        \"  host: db.local\",\n        \"  port: 5432\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"YAML with comments\", () => {\n      const yaml = [\n        \"# This is a config file\",\n        \"name: test\",\n        \"# Another comment\",\n        \"value: 42\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"YAML with list items\", () => {\n      const yaml = [\n        \"fruits:\",\n        \"  - apple\",\n        \"  - banana\",\n        \"  - cherry\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"YAML with quoted values\", () => {\n      const yaml = `name: \"Alice\"\\nmotto: 'hello world'`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"empty input\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"whitespace-only input\", () => {\n      const result = validateYaml(\"   \\n  \\n  \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"document markers\", () => {\n      const yaml = [\"---\", \"name: test\", \"...\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"tab indentation\", () => {\n      const yaml = \"server:\\n\\thost: localhost\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0]).toContain(\"Tab character\");\n    });\n\n    test(\"inconsistent indentation\", () => {\n      const yaml = [\n        \"server:\",\n        \"  host: localhost\",\n        \"   port: 8080\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.includes(\"Inconsistent indentation\"))).toBe(true);\n    });\n\n    test(\"unclosed double quote\", () => {\n      const yaml = `name: \"Alice`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.includes(\"Unclosed double quote\"))).toBe(true);\n    });\n\n    test(\"unclosed single quote\", () => {\n      const yaml = `name: 'Alice`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.includes(\"Unclosed single quote\"))).toBe(true);\n    });\n\n    test(\"duplicate keys at same level\", () => {\n      const yaml = [\"name: Alice\", \"age: 30\", \"name: Bob\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.includes('Duplicate key \"name\"'))).toBe(true);\n    });\n\n    test(\"invalid structure — missing colon\", () => {\n      const yaml = [\"name: Alice\", \"this is not valid yaml\", \"age: 30\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.includes(\"Invalid structure\"))).toBe(true);\n    });\n\n    test(\"multiple errors detected at once\", () => {\n      const yaml = [\"name: Alice\", \"name: Bob\", 'value: \"unclosed'].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(2);\n    });\n  });\n});\n"
      },
