        "content": "/**\n * CLI entry point for the YAML validator.\n * Usage: bun run src/validate-yaml.ts <file>\n */\n\nimport { validateYaml } from \"./yaml-validator\";\n\nasync function main(): Promise<void> {\n  const filePath = process.argv[2];\n\n  if (!filePath) {\n    console.error(\"Usage: bun run src/validate-yaml.ts <file>\");\n    process.exit(1);\n  }\n\n  let content: string;\n  try {\n    content = await Bun.file(filePath).text();\n  } catch {\n    console.error(`Error: Cannot read file \"${filePath}\"`);\n    process.exit(1);\n  }\n\n  const result = validateYaml(content);\n\n  if (result.valid) {\n    console.log(\"✓ Valid YAML\");\n    process.exit(0);\n  } else {\n    console.error(\"✗ Invalid YAML:\");\n    for (const error of result.errors) {\n      console.error(`  ${error}`);\n    }\n    process.exit(1);\n  }\n}\n\nmain();\n"
