/**
 * YAML validator module — validates basic YAML structure without external dependencies.
 */

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export function validateYaml(input: string): ValidationResult {
  if (input.trim().length === 0) {
    return { valid: true, errors: [] };
  }

  const lines = input.split("\n");
  const errors: string[] = [
    ...checkIndentation(lines),
    ...checkQuotes(lines),
    ...checkDuplicateKeys(lines),
    ...checkStructure(lines),
  ];

  return { valid: errors.length === 0, errors };
}

function isContentLine(line: string): boolean {
  const trimmed = line.trim();
  return trimmed.length > 0 && !trimmed.startsWith("#");
}

function getIndentLevel(line: string): number {
  const match = line.match(/^(\s*)/);
  return match ? match[1].length : 0;
}

function checkIndentation(lines: string[]): string[] {
  const errors: string[] = [];
  let detectedIndentWidth = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!isContentLine(line)) continue;

    if (line.includes("\t")) {
      errors.push(`Line ${i + 1}: Tab character found — YAML requires spaces for indentation`);
      continue;
    }

    const indent = getIndentLevel(line);
    if (indent === 0) continue;

    if (detectedIndentWidth === 0) {
      detectedIndentWidth = indent;
    } else if (indent % detectedIndentWidth !== 0) {
      errors.push(
        `Line ${i + 1}: Inconsistent indentation (${indent} spaces, expected multiple of ${detectedIndentWidth})`
      );
    }
  }

  return errors;
}

function checkQuotes(lines: string[]): string[] {
  const errors: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!isContentLine(line)) continue;

    const trimmed = line.trim();

    for (const quote of ["'", '"'] as const) {
      const count = countUnescapedQuotes(trimmed, quote);
      if (count % 2 !== 0) {
        const quoteType = quote === "'" ? "single" : "double";
        errors.push(`Line ${i + 1}: Unclosed ${quoteType} quote`);
      }
    }
  }

  return errors;
}

function countUnescapedQuotes(text: string, quote: string): number {
  let count = 0;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === quote && (i === 0 || text[i - 1] !== "\\")) {
      count++;
    }
  }
  return count;
}

function checkDuplicateKeys(lines: string[]): string[] {
  const errors: string[] = [];
  const keysByIndent = new Map<number, Set<string>>();
  let lastIndent = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!isContentLine(line)) continue;

    const trimmed = line.trim();
    if (trimmed.startsWith("- ")) continue;

    const colonIndex = trimmed.indexOf(":");
    if (colonIndex <= 0) continue;

    const key = trimmed.substring(0, colonIndex).trim();
    const indent = getIndentLevel(line);

    if (indent < lastIndent) {
      for (const [level] of keysByIndent) {
        if (level > indent) {
          keysByIndent.delete(level);
        }
      }
    }

    if (!keysByIndent.has(indent)) {
      keysByIndent.set(indent, new Set());
    }

    const keysAtLevel = keysByIndent.get(indent)!;
    if (keysAtLevel.has(key)) {
      errors.push(`Line ${i + 1}: Duplicate key "${key}" at indentation level ${indent}`);
    } else {
      keysAtLevel.add(key);
    }

    lastIndent = indent;
  }

  return errors;
}

function checkStructure(lines: string[]): string[] {
  const errors: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!isContentLine(line)) continue;

    const trimmed = line.trim();

    if (trimmed === "---" || trimmed === "...") continue;

    if (trimmed.startsWith("- ") || trimmed === "-") continue;

    if (!trimmed.includes(":")) {
      errors.push(`Line ${i + 1}: Invalid structure — expected key-value pair or list item`);
    }
  }

  return errors;
}

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple key-value pairs", () => {
      const yaml = `name: Alice\nage: 30\ncity: Wonderland`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("nested YAML", () => {
      const yaml = [
        "server:",
        "  host: localhost",
        "  port: 8080",
        "database:",
        "  host: db.local",
        "  port: 5432",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("YAML with comments", () => {
      const yaml = [
        "# This is a config file",
        "name: test",
        "# Another comment",
        "value: 42",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("YAML with list items", () => {
      const yaml = [
        "fruits:",
        "  - apple",
        "  - banana",
        "  - cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("YAML with quoted values", () => {
      const yaml = `name: "Alice"\nmotto: 'hello world'`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("empty input", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("whitespace-only input", () => {
      const result = validateYaml("   \n  \n  ");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document markers", () => {
      const yaml = ["---", "name: test", "..."].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("invalid YAML", () => {
    test("tab indentation", () => {
      const yaml = "server:\n\thost: localhost";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0]).toContain("Tab character");
    });

    test("inconsistent indentation", () => {
      const yaml = [
        "server:",
        "  host: localhost",
        "   port: 8080",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("Inconsistent indentation"))).toBe(true);
    });

    test("unclosed double quote", () => {
      const yaml = `name: "Alice`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("Unclosed double quote"))).toBe(true);
    });

    test("unclosed single quote", () => {
      const yaml = `name: 'Alice`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("Unclosed single quote"))).toBe(true);
    });

    test("duplicate keys at same level", () => {
      const yaml = ["name: Alice", "age: 30", "name: Bob"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes('Duplicate key "name"'))).toBe(true);
    });

    test("invalid structure — missing colon", () => {
      const yaml = ["name: Alice", "this is not valid yaml", "age: 30"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.includes("Invalid structure"))).toBe(true);
    });

    test("multiple errors detected at once", () => {
      const yaml = ["name: Alice", "name: Bob", 'value: "unclosed'].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });
  });
});

/**
 * CLI entry point for the YAML validator.
 * Usage: bun run src/validate-yaml.ts <file>
 */

import { validateYaml } from "./yaml-validator";

async function main(): Promise<void> {
  const filePath = process.argv[2];

  if (!filePath) {
    console.error("Usage: bun run src/validate-yaml.ts <file>");
    process.exit(1);
  }

  let content: string;
  try {
    content = await Bun.file(filePath).text();
  } catch {
    console.error(`Error: Cannot read file "${filePath}"`);
    process.exit(1);
  }

  const result = validateYaml(content);

  if (result.valid) {
    console.log("✓ Valid YAML");
    process.exit(0);
  } else {
    console.error("✗ Invalid YAML:");
    for (const error of result.errors) {
      console.error(`  ${error}`);
    }
    process.exit(1);
  }
}

main();

